/// <summary>
/// Class <c>METPOContinuingPermissionNoticeContractUIBuilder</c> UI Builder.
/// </summary>
class METPOContinuingPermissionNoticeContractUIBuilder extends SrsReportDataContractUIBuilder
{
    DialogField vendInvoiceIdField;
    DialogField purchIdField;
    DialogField threadIdField;
    DialogField isAutoGenerateCPNoticeField;

}

Method.Source:
/// <summary>
/// Posts build.
/// </summary>
public void postBuild()
{
    METPOContinuingPermissionNoticeContract contract;
    str menuItemName;

    contract = this.dataContractObject() as METPOContinuingPermissionNoticeContract;

    vendInvoiceIdField = this.bindInfo().getDialogField(contract, methodStr(METPOContinuingPermissionNoticeContract, parmInvoiceId));
    purchIdField = this.bindInfo().getDialogField(contract, methodStr(METPOContinuingPermissionNoticeContract, parmPurchId));
    threadIdField = this.bindInfo().getDialogField(contract, methodStr(METPOContinuingPermissionNoticeContract, parmThreadCount));
    isAutoGenerateCPNoticeField = this.bindInfo().getDialogField(contract, methodStr(METPOContinuingPermissionNoticeContract, parmIsAutoGenerateCPNotice));

    menuItemName = this.controller().parmArgs().menuItemName();

    if (menuItemName == menuItemActionStr(METPurchParmPackingSlip))
    {
        vendInvoiceIdField.visible(false);
        purchIdField.visible(false);
    }
    else
    {
        threadIdField.visible(false);
        isAutoGenerateCPNoticeField.visible(false);
    }

}
